function generateSmartHPASearchURL(params) {
    const baseUrl = 'https://www.proteinatlas.org/search';
    if (!params) return baseUrl;
    let searchParams = [];
    const { searchField, class: className, subclass } = params;

    const encode = (str) => encodeURIComponent(str).replace(/%20/g, '+');

    switch (searchField) {
        case 'Protein class':
            if (className && className !== 'Any') {
                let paramValue = `protein_class:${encode(className)}`;
                if (subclass && subclass !== 'Any') {
                    paramValue += `;${encode(subclass)}`;
                }
                searchParams.push(paramValue);
            }
            break;

        case 'Tissue category (RNA)':
            if (className && className !== 'Any') {
                let paramValue = `tissue_category_rna:${encode(className)}`;
                if (subclass && subclass !== 'Any') {
                    paramValue += `;${encode(subclass)}`;
                }
                searchParams.push(paramValue);
            }
            break;

        case 'Subcellular location (ICC)':
            if (className && className !== 'Any') {
                searchParams.push(`subcell_location:${encode(className)}`);
            }
            break;

        case 'Prognostic cancer':
            if (className && className !== 'Any') {
                let paramValue = `prognostic:${encode(className)}`;
                if (subclass && subclass !== 'Any') {
                    paramValue += `;${encode(subclass)}`;
                }
                searchParams.push(paramValue);
            }
            break;

        default:
            if (className && className !== 'Any') {
                searchParams.push(encode(className));
            }
    }
    return searchParams.length > 0 ? `${baseUrl}/${searchParams.join(';')}` : baseUrl;
}

/**
 * Generates a formatted string of options for a given category.
 * This is used to create the focused, small prompts for the AI.
 * @param {string} metaCategory The top-level category (e.g., 'TISSUE').
 * @param {object} searchFields A limited object of search fields to format.
 * @returns {string} A formatted string for the AI prompt.
 */
function getFormattedOptionsForCategory(metaCategory, searchFields) {
    let formattedOptions = `CATEGORY: ${metaCategory}\n\n`;
    for (const searchField of Object.keys(searchFields)) {
        const detailedOptions = detailedSearchOptions[metaCategory]?.[searchField] || {};
        formattedOptions += `SEARCH FIELD: ${searchField}\n`;
        if (Object.keys(detailedOptions).length > 0) {
            formattedOptions += `Available Classes:\n`;
            for (const [className, subclasses] of Object.entries(detailedOptions)) {
                formattedOptions += `  • ${className}`;
                if (subclasses.length > 1 || (subclasses.length === 1 && subclasses[0] !== 'Any')) {
                    formattedOptions += `\n    Subclasses: ${subclasses.join(', ')}`;
                }
                formattedOptions += `\n`;
            }
        }
        formattedOptions += `\n`;
    }
    return formattedOptions;
}


